CREATE OR REPLACE PACKAGE BODY lookups.country AS

  FUNCTION country_name(p_code IN VARCHAR2) RETURN VARCHAR2 DETERMINISTIC RESULT_CACHE IS
    l_row VARCHAR2(4000);
    PRAGMA UDF;
  BEGIN
    BEGIN
      select name
      INTO l_row
      FROM countries where code = p_code;
    EXCEPTION
      WHEN NO_DATA_FOUND THEN RAISE;
      WHEN TOO_MANY_ROWS THEN RAISE;
    END;
    RETURN l_row;
  END country_name;

  PROCEDURE audit_log(p_event IN VARCHAR2) IS
    PRAGMA AUTONOMOUS_TRANSACTION;
  BEGIN
    BEGIN
    insert into audit_tbl(event, ts) values (p_event, sysdate);
      COMMIT;
    EXCEPTION
      WHEN OTHERS THEN
        ROLLBACK;
        RAISE;
    END;
  END audit_log;
END country;
/